namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            int orderQty = CalculateOrderQuantity(item, season);
            if (orderQty <= 0)
                continue;
            if (string.IsNullOrEmpty(item.Sku))
                continue;

            bool placed = supplier.PlaceOrder(item.Sku, orderQty);
            AddPlanEntry(plan, item, orderQty, placed);
        }

        return plan;
    }

    private static int CalculateOrderQuantity(StockItem item, int season)
    {
        if (item.OnHand < 0)
            return 0;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return 0;

        int deficit = item.ReorderPoint - available;
        int orderQty = CalculateBaseOrderQuantity(deficit);
        return ApplySeasonalAdjustment(orderQty, season);
    }

    private static int CalculateBaseOrderQuantity(int deficit)
    {
        if (deficit <= 0)
            return 0;
        if (deficit < 10)
            return 10;
        if (deficit < 100)
            return deficit;

        return deficit + 50;
    }

    private static int ApplySeasonalAdjustment(int orderQty, int season)
    {
        if (season == 4 && orderQty > 0)
            return (int)(orderQty * 1.5);
        if (season == 1)
            return orderQty / 2;

        return orderQty;
    }

    private static void AddPlanEntry(List<string> plan, StockItem item, int orderQty, bool placed)
    {
        if (placed && orderQty > 200)
            plan.Add($"{item.Sku}:LARGE:{orderQty}");
        else if (placed)
            plan.Add($"{item.Sku}:{orderQty}");
        else
            plan.Add($"{item.Sku}:FAILED");
    }
}
